type Product = { id: string; name: string; priceCents: number };

interface Cache {
    get(key: string): Promise<string | null>;
    set(key: string, value: string, options: { EX: number }): Promise<unknown>;
    del(key: string): Promise<unknown>;
}

interface Database {
    product(id: string): Promise<Product | null>;
    updateProduct(id: string, priceCents: number): Promise<Product>;
}

const TTL_SECONDS = 300;
const inFlight = new Map<string, Promise<Product | null>>();

function keyFor(id: string): string {
    return `product:${id}`;
}

async function readCached(cache: Cache, key: string): Promise<Product | null> {
    try {
        const raw = await cache.get(key);
        return raw === null ? null : (JSON.parse(raw) as Product);
    } catch {
        return null;
    }
}

async function writeCached(cache: Cache, key: string, product: Product): Promise<void> {
    try {
        await cache.set(key, JSON.stringify(product), { EX: TTL_SECONDS });
    } catch {
        // A cache outage must not fail a read the database can answer.
    }
}

async function loadProduct(cache: Cache, db: Database, key: string, id: string): Promise<Product | null> {
    const product = await db.product(id);
    if (product !== null) {
        await writeCached(cache, key, product);
    }
    return product;
}

export async function getProduct(cache: Cache, db: Database, id: string): Promise<Product | null> {
    const key = keyFor(id);
    const cached = await readCached(cache, key);
    if (cached !== null) {
        return cached;
    }
    const pending = inFlight.get(key);
    if (pending !== undefined) {
        return pending;
    }
    const load = loadProduct(cache, db, key, id).finally(function clear() {
        inFlight.delete(key);
    });
    inFlight.set(key, load);
    return load;
}

export async function updatePrice(cache: Cache, db: Database, id: string, priceCents: number): Promise<Product> {
    const product = await db.updateProduct(id, priceCents);
    try {
        await cache.del(keyFor(id));
    } catch {
        // The TTL bounds how long a stale copy survives a failed invalidation.
    }
    return product;
}
